// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title CredentialVault - Manages worker node authentication for K8s job scheduler
 * @notice Each worker registers with a credential hash; jobs are dispatched via signed messages
 */
contract CredentialVault is Ownable {
    using ECDSA for bytes32;

    struct WorkerNode {
        bytes32 credentialHash;
        uint256 lastAuthTimestamp;
        uint8 failedAttempts;
        bool isLocked;
        bool isRegistered;
    }

    mapping(address => WorkerNode) public workers;
    mapping(bytes32 => bool) public usedNonces;

    uint8 public constant MAX_FAILED_ATTEMPTS = 5;
    uint256 public constant LOCKOUT_DURATION = 1 hours;
    uint256 public constant AUTH_COOLDOWN = 30 seconds;

    event WorkerRegistered(address indexed worker, bytes32 credentialHash);
    event AuthAttempt(address indexed worker, bool success);
    event WorkerLocked(address indexed worker);
    event WorkerUnlocked(address indexed worker);
    event JobDispatched(address indexed worker, bytes32 jobId);

    modifier onlyRegistered(address worker) {
        require(workers[worker].isRegistered, "Worker not registered");
        _;
    }

    constructor() Ownable() {}

    function registerWorker(address worker, bytes32 credentialHash) external onlyOwner {
        require(!workers[worker].isRegistered, "Already registered");
        workers[worker] = WorkerNode({
            credentialHash: credentialHash,
            lastAuthTimestamp: 0,
            failedAttempts: 0,
            isLocked: false,
            isRegistered: true
        });
        emit WorkerRegistered(worker, credentialHash);
    }

    function _resetFailedAttempts(address worker) internal {
        workers[worker].failedAttempts = 0;
    }

    function _checkAndUpdateLockStatus(address worker) internal returns (bool) {
        WorkerNode storage node = workers[worker];
        if (node.isLocked) {
            if (block.timestamp >= node.lastAuthTimestamp + LOCKOUT_DURATION) {
                node.isLocked = false;
                _resetFailedAttempts(worker);
                emit WorkerUnlocked(worker);
                return false; // was locked but now unlocked
            }
            return true; // still locked
        }
        return false; // not locked
    }

    function _validateCredentialTiming(address worker) internal view returns (bool) {
        WorkerNode storage node = workers[worker];
        if (node.lastAuthTimestamp == 0) return true;
        return block.timestamp >= node.lastAuthTimestamp + AUTH_COOLDOWN;
    }

    function _incrementFailures(address worker) internal {
        WorkerNode storage node = workers[worker];
        // Overflow-safe increment with ceiling at MAX_FAILED_ATTEMPTS
        if (node.failedAttempts < MAX_FAILED_ATTEMPTS) {
            node.failedAttempts += 1;
        }
        if (node.failedAttempts >= MAX_FAILED_ATTEMPTS) {
            node.isLocked = true;
            emit WorkerLocked(worker);
        }
    }

    function authenticate(
        address worker,
        bytes32 credential,
        bytes32 nonce,
        bytes memory signature
    ) external onlyRegistered(worker) returns (bool) {
        require(!usedNonces[nonce], "Nonce already used");

        // Check lock status (may unlock if duration passed)
        bool stillLocked = _checkAndUpdateLockStatus(worker);
        require(!stillLocked, "Worker is locked out");

        // Validate timing between attempts
        require(_validateCredentialTiming(worker), "Auth cooldown active");

        // Verify the signature matches the worker's address
        bytes32 messageHash = keccak256(abi.encodePacked(worker, credential, nonce));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(signature);
        require(signer == worker, "Invalid signature");

        // Mark nonce as used
        usedNonces[nonce] = true;

        // Update timestamp BEFORE credential check
        workers[worker].lastAuthTimestamp = block.timestamp;

        // Verify credential
        bytes32 computedHash = keccak256(abi.encodePacked(credential, nonce));
        if (computedHash == workers[worker].credentialHash) {
            _resetFailedAttempts(worker);
            emit AuthAttempt(worker, true);
            return true;
        } else {
            _incrementFailures(worker);
            emit AuthAttempt(worker, false);
            return false;
        }
    }

    function dispatchJob(
        address worker,
        bytes32 jobId,
        bytes32 credential,
        bytes32 nonce,
        bytes memory signature
    ) external onlyRegistered(worker) {
        bool authed = this.authenticate(worker, credential, nonce, signature);
        require(authed, "Authentication failed");
        emit JobDispatched(worker, jobId);
    }

    function getWorkerStatus(address worker) external view returns (
        bool isRegistered,
        bool isLocked,
        uint8 failedAttempts,
        uint256 lastAuth
    ) {
        WorkerNode storage node = workers[worker];
        return (node.isRegistered, node.isLocked, node.failedAttempts, node.lastAuthTimestamp);
    }

    function adminUnlock(address worker) external onlyOwner onlyRegistered(worker) {
        workers[worker].isLocked = false;
        _resetFailedAttempts(worker);
        emit WorkerUnlocked(worker);
    }
}
